#import <UIKit/UIKit.h>
#import <UniformTypeIdentifiers/UniformTypeIdentifiers.h>
extern BOOL PXExtractPackage(NSURL *,NSURL *,void(^)(NSString *),NSDictionary **,NSError **);
@interface PXController:UIViewController<UIDocumentPickerDelegate>
@property UILabel *status;@property UIButton *choose;@property BOOL busy;
@end
@implementation PXController
- (void)viewDidLoad{[super viewDidLoad];self.title=@"GOG PKG Extractor";self.overrideUserInterfaceStyle=UIUserInterfaceStyleDark;self.view.backgroundColor=[UIColor colorWithRed:.04 green:.07 blue:.12 alpha:1];UIStackView *stack=[UIStackView new];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=26;stack.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:stack];UIImageView *icon=[[UIImageView alloc]initWithImage:[UIImage systemImageNamed:@"shippingbox.and.arrow.backward.fill"]];icon.contentMode=UIViewContentModeScaleAspectFit;icon.tintColor=UIColor.systemTealColor;[icon.heightAnchor constraintEqualToConstant:96].active=YES;[stack addArrangedSubview:icon];UILabel *title=[UILabel new];title.text=@"From package\nto game folder.";title.numberOfLines=0;title.font=[UIFont systemFontOfSize:32 weight:UIFontWeightBold];[stack addArrangedSubview:title];UILabel *intro=[UILabel new];intro.text=@"Extract your GOG Mac copy of Hollow Knight 1.5.12620 or Silksong 1.0.30000 entirely on this iPhone. Then select the extracted game folder in Hollow Builder. Other PKG formats are not supported.";intro.numberOfLines=0;[stack addArrangedSubview:intro];UIButtonConfiguration *config;if(@available(iOS 26.0,*))config=[UIButtonConfiguration prominentGlassButtonConfiguration];else config=[UIButtonConfiguration filledButtonConfiguration];config.title=@"Choose GOG .pkg";self.choose=[UIButton buttonWithConfiguration:config primaryAction:nil];[self.choose addTarget:self action:@selector(selectPackage) forControlEvents:UIControlEventTouchUpInside];[stack addArrangedSubview:self.choose];self.status=[UILabel new];self.status.numberOfLines=0;self.status.text=@"Original packages stay unchanged. Installer scripts are never executed. Keep at least 5.5 GB free for Hollow Knight or 9 GB for Silksong, in addition to the package.";self.status.font=[UIFont preferredFontForTextStyle:UIFontTextStyleFootnote];[stack addArrangedSubview:self.status];UILayoutGuide *safe=self.view.safeAreaLayoutGuide;[NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:safe.leadingAnchor constant:26],[stack.trailingAnchor constraintEqualToAnchor:safe.trailingAnchor constant:-26],[stack.topAnchor constraintEqualToAnchor:safe.topAnchor constant:28],[stack.bottomAnchor constraintLessThanOrEqualToAnchor:safe.bottomAnchor constant:-20]]];}
- (void)selectPackage{if(self.busy)return;UTType *pkg=[UTType typeWithFilenameExtension:@"pkg"]?:UTTypeData;UIDocumentPickerViewController *picker=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[pkg,UTTypeData] asCopy:NO];picker.delegate=self;[self presentViewController:picker animated:YES completion:nil];}
- (void)documentPickerWasCancelled:(UIDocumentPickerViewController *)controller{}
- (void)documentPicker:(UIDocumentPickerViewController *)controller didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{NSURL *source=urls.firstObject;if(!source)return;self.busy=YES;self.choose.enabled=NO;UIApplication.sharedApplication.idleTimerDisabled=YES;self.status.text=@"Checking package and available storage…";dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{BOOL access=[source startAccessingSecurityScopedResource];NSString *apps=NSBundle.mainBundle.bundlePath.stringByDeletingLastPathComponent,*base=[apps.lastPathComponent isEqual:@"Applications"]?apps.stringByDeletingLastPathComponent:NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject;NSString *parent=[base stringByAppendingPathComponent:@"Extracted GOG Games"];NSFileManager *fm=NSFileManager.defaultManager;NSError *error=nil;BOOL prepared=[fm createDirectoryAtPath:parent withIntermediateDirectories:YES attributes:nil error:&error];NSString *name=[source.lastPathComponent.stringByDeletingPathExtension stringByReplacingOccurrencesOfString:@"/" withString:@"-"];if(name.length>100)name=[name substringToIndex:100];NSString *folder=[parent stringByAppendingPathComponent:name];NSUInteger count=2;while([fm fileExistsAtPath:folder])folder=[parent stringByAppendingPathComponent:[NSString stringWithFormat:@"%@-%lu",name,(unsigned long)count++]];NSDictionary *report=nil;BOOL okay=prepared&&PXExtractPackage(source,[NSURL fileURLWithPath:folder isDirectory:YES],^(NSString *message){dispatch_async(dispatch_get_main_queue(),^{self.status.text=message;});},&report,&error);if(access)[source stopAccessingSecurityScopedResource];if(okay)[[NSJSONSerialization dataWithJSONObject:report options:NSJSONWritingPrettyPrinted error:nil] writeToFile:[folder stringByAppendingPathComponent:@"Extraction-report.json"] atomically:YES];dispatch_async(dispatch_get_main_queue(),^{self.busy=NO;self.choose.enabled=YES;UIApplication.sharedApplication.idleTimerDisabled=NO;self.status.text=okay?@"Extraction complete. Open Hollow Builder and select your game under Files → Extracted GOG Games. Inside LiveContainer, this folder is under On My iPhone → LiveContainer.":error.localizedDescription?:@"Extraction failed; the original package is preserved.";UIAlertController *notice=[UIAlertController alertControllerWithTitle:okay?@"Game folder ready":@"Could not extract package" message:self.status.text preferredStyle:UIAlertControllerStyleAlert];[notice addAction:[UIAlertAction actionWithTitle:@"Done" style:UIAlertActionStyleDefault handler:nil]];[self presentViewController:notice animated:YES completion:nil];});});}
@end
